#include "glove_core.h"

#include <math.h>
#include <string.h>

#include "gesture_model.h"   /* generated by ml/export_c.py: gesture_predict_proba() */

_Static_assert(GESTURE_MODEL_FEATURES == GLOVE_FEATURES, "model and feature extractor disagree");
_Static_assert(GESTURE_WINDOW == GLOVE_WINDOW, "window differs from the one used for training");
_Static_assert(GESTURE_STEP == GLOVE_STEP, "step differs from the one used for training");

void glove_init(glove_t *g) {
    memset(g, 0, sizeof(*g));
    g->threshold = 0.70f;
    g->open_adc = 3200;
    g->closed_adc = 3900;
    g->lo = 0.10f;
    g->hi = 0.90f;
    g->vmax = 255;
    g->ema_alpha = 0.4f;
    g->deadband = 25;
    g->max_rise = 60;
    for (int i = 0; i < GESTURE_COUNT; i++) g->mapping[i] = CMD_STOP;
    g->mapping[GESTURE_OPEN_HAND] = CMD_FORWARD;
    g->mapping[GESTURE_TURN_LEFT] = CMD_TURN_LEFT;
    g->mapping[GESTURE_TURN_RIGHT] = CMD_TURN_RIGHT;
}

void glove_set_threshold(glove_t *g, float threshold) {
    if (threshold < 0.5f) threshold = 0.5f;
    if (threshold > 0.95f) threshold = 0.95f;
    g->threshold = threshold;
}

void glove_set_calibration(glove_t *g, int open_adc, int closed_adc) {
    g->open_adc = open_adc;
    g->closed_adc = closed_adc;
}

void glove_set_mapping(glove_t *g, int gesture, glove_command_t command) {
    if (gesture >= 0 && gesture < GESTURE_COUNT && gesture != GESTURE_UNKNOWN) {
        g->mapping[gesture] = command;       /* the unknown gesture always stops */
    }
}

/* Median of n <= GLOVE_MEDIAN values (same convention as numpy: mean of the two middle values if n is even). */
static float median_of(const float *v, int n) {
    float s[GLOVE_MEDIAN];
    for (int i = 0; i < n; i++) {
        float x = v[i];
        int j = i;
        while (j > 0 && s[j - 1] > x) {
            s[j] = s[j - 1];
            j--;
        }
        s[j] = x;
    }
    return (n % 2) ? s[n / 2] : 0.5f * (s[n / 2 - 1] + s[n / 2]);
}

/* Same 40 features, same order as ml/features.py: [mean, std, min, max, energy] x [7 channels, |acc|]. */
static void extract_features(const float win[GLOVE_WINDOW][GLOVE_CHANNELS], float f[GLOVE_FEATURES]) {
    const int C = GLOVE_CHANNELS + 1;
    for (int c = 0; c < C; c++) {
        float v[GLOVE_WINDOW];
        for (int i = 0; i < GLOVE_WINDOW; i++) {
            v[i] = (c < GLOVE_CHANNELS)
                       ? win[i][c]
                       : sqrtf(win[i][1] * win[i][1] + win[i][2] * win[i][2] + win[i][3] * win[i][3]);
        }
        double sum = 0.0, sq = 0.0;
        float mn = v[0], mx = v[0];
        for (int i = 0; i < GLOVE_WINDOW; i++) {
            sum += v[i];
            sq += (double)v[i] * v[i];
            if (v[i] < mn) mn = v[i];
            if (v[i] > mx) mx = v[i];
        }
        const double mean = sum / GLOVE_WINDOW;
        double var = 0.0;
        for (int i = 0; i < GLOVE_WINDOW; i++) var += ((double)v[i] - mean) * ((double)v[i] - mean);
        f[0 * C + c] = (float)mean;
        f[1 * C + c] = (float)sqrt(var / GLOVE_WINDOW);
        f[2 * C + c] = mn;
        f[3 * C + c] = mx;
        f[4 * C + c] = (float)(sq / GLOVE_WINDOW);
    }
}

/* Open hand = fast, closed fist = 0 (mirror of ml/speed.py flex_to_speed). */
static int flex_to_speed(const glove_t *g, float flex) {
    const int span = g->closed_adc - g->open_adc;
    if (span == 0) return 0;
    float bend = (flex - (float)g->open_adc) / (float)span;
    if (bend < 0.0f) bend = 0.0f;
    if (bend > 1.0f) bend = 1.0f;
    float x = ((1.0f - bend) - g->lo) / (g->hi - g->lo);
    if (x < 0.0f) x = 0.0f;
    if (x > 1.0f) x = 1.0f;
    return (int)nearbyintf(x * (float)g->vmax);   /* round half to even, like Python's round() */
}

static int speed_for(glove_t *g, glove_command_t cmd, float flex_mean) {
    if (!g->flex_init) {
        g->flex = flex_mean;
        g->flex_init = 1;
    } else if (fabsf(flex_mean - g->flex) >= (float)g->deadband) {
        g->flex = g->ema_alpha * flex_mean + (1.0f - g->ema_alpha) * g->flex;
    }
    if (cmd == CMD_STOP) {
        g->speed = 0;
        return 0;
    }
    const int target = flex_to_speed(g, g->flex);
    if (target > g->speed) {
        const int up = g->speed + g->max_rise;
        g->speed = target < up ? target : up;       /* accelerate gradually */
    } else {
        g->speed = target;                          /* slow down at once */
    }
    return g->speed;
}

int glove_push(glove_t *g, const float row[GLOVE_CHANNELS], glove_output_t *out) {
    /* 1. spike filter: median of the last GLOVE_MEDIAN samples, channel by channel */
    memcpy(g->raw[g->raw_head], row, sizeof(float) * GLOVE_CHANNELS);
    g->raw_head = (g->raw_head + 1) % GLOVE_MEDIAN;
    if (g->raw_count < GLOVE_MEDIAN) g->raw_count++;

    float filtered[GLOVE_CHANNELS];
    for (int c = 0; c < GLOVE_CHANNELS; c++) {
        float v[GLOVE_MEDIAN];
        for (int i = 0; i < g->raw_count; i++) v[i] = g->raw[i][c];   /* order does not matter for a median */
        filtered[c] = median_of(v, g->raw_count);
    }

    /* 2. sliding window */
    memcpy(g->win[g->win_head], filtered, sizeof(filtered));
    g->win_head = (g->win_head + 1) % GLOVE_WINDOW;
    if (g->win_count < GLOVE_WINDOW) g->win_count++;
    g->since++;
    if (g->win_count < GLOVE_WINDOW || g->since < GLOVE_STEP) return 0;
    g->since = 0;

    /* 3. features and Random Forest */
    float feats[GLOVE_FEATURES];
    extract_features((const float (*)[GLOVE_CHANNELS])g->win, feats);
    float proba[GESTURE_COUNT];
    if (gesture_predict_proba(feats, GLOVE_FEATURES, proba, GESTURE_COUNT) != 0) {
        for (int i = 0; i < GESTURE_COUNT; i++) proba[i] = 0.0f;
        proba[GESTURE_UNKNOWN] = 1.0f;                 /* model error: fail safe */
    }

    /* 4. confidence threshold: not sure enough means unknown, which means STOP */
    int top = 0;
    for (int i = 1; i < GESTURE_COUNT; i++) {
        if (proba[i] > proba[top]) top = i;
    }
    const int gesture = (proba[top] >= g->threshold) ? top : GESTURE_UNKNOWN;
    const glove_command_t cmd = g->mapping[gesture];

    /* 5. speed from the flex value of the last GLOVE_STEP samples */
    float flex_sum = 0.0f;
    for (int k = 0; k < GLOVE_STEP; k++) {
        flex_sum += g->win[(g->win_head + GLOVE_WINDOW - 1 - k) % GLOVE_WINDOW][0];
    }
    const int speed = speed_for(g, cmd, flex_sum / GLOVE_STEP);

    out->gesture = gesture;
    out->confidence = proba[gesture];
    out->command = cmd;
    out->speed = speed;
    memcpy(out->proba, proba, sizeof(proba));
    return 1;
}